"""
Bootstrap and Masterdir Manager for xbps-src.

Configures environment, creates etc/conf, and initializes masterdir.
"""

from __future__ import annotations

import logging
import os
import subprocess
from pathlib import Path
from typing import Optional

from core.adapter import RepoAdapter
from builder.runner import get_host_arch, needs_alt_host

logger = logging.getLogger("autopkg.builder.bootstrap")


class MasterdirBootstrapper:
    def __init__(self, repo_adapter: RepoAdapter) -> None:
        self.adapter = repo_adapter
        self.root_dir = self.adapter.root_dir
        self.xbps_src = self.root_dir / "xbps-src"
        self.etc_conf = self.root_dir / "etc" / "conf"

    def configure_environment(
        self,
        allow_restricted: bool = True,
        makejobs: Optional[int] = None,
        custom_options: Optional[dict] = None,
    ) -> None:
        """Write optimal settings into etc/conf."""
        self.etc_conf.parent.mkdir(parents=True, exist_ok=True)

        lines = [
            "# Generated by autopkg-engine",
            f"XBPS_ALLOW_RESTRICTED={'yes' if allow_restricted else 'no'}",
            "XBPS_CHROOT_CMD=uchroot",
        ]

        if makejobs:
            lines.append(f"XBPS_MAKEJOBS={makejobs}")
        else:
            cpu_count = os.cpu_count() or 2
            lines.append(f"XBPS_MAKEJOBS={cpu_count}")

        if custom_options:
            for k, v in custom_options.items():
                lines.append(f"{k}={v}")

        with open(self.etc_conf, "w", encoding="utf-8") as f:
            f.write("\n".join(lines) + "\n")
        logger.info("Wrote %s with optimal build flags", self.etc_conf)

    def is_bootstrapped(self, arch: str = "x86_64", host_arch: Optional[str] = None) -> bool:
        host = host_arch or get_host_arch()
        if arch != host:
            masterdir_arch = self.root_dir / f"masterdir-{arch}"
            if masterdir_arch.is_dir():
                return (masterdir_arch / "usr" / "bin").is_dir()
        masterdir = self.root_dir / "masterdir"
        return masterdir.is_dir() and (masterdir / "usr" / "bin").is_dir()

    def bootstrap(self, arch: str = "x86_64", host_arch: Optional[str] = None) -> bool:
        """Run binary-bootstrap for the target architecture."""
        if not self.xbps_src.is_file():
            logger.error("xbps-src binary not found in %s", self.root_dir)
            return False

        if not self.etc_conf.is_file():
            self.configure_environment()

        host = host_arch or get_host_arch()
        cmd = [str(self.xbps_src)]
        if needs_alt_host(arch, host):
            cmd += ["-A", arch, "-m", f"masterdir-{arch}"]
        elif arch != host:
            cmd += ["-a", arch, "-m", f"masterdir-{arch}"]
        cmd += ["binary-bootstrap", arch]

        logger.info("Executing bootstrap command: %s", " ".join(cmd))
        res = subprocess.run(cmd, cwd=str(self.root_dir), check=False)
        return res.returncode == 0
